const listTenantEffectiveConfigurations = `-- name: ListTenantEffectiveConfigurations :many
WITH tenant_configs AS (
    SELECT 
        kv.key as config_full_key,
        split_part(kv.key, '.', 1) as module_name,
        split_part(kv.key, '.', 2) as config_key,
        kv.value,
        'tenant' as source
    FROM tenant_configurations tc,
         jsonb_each(tc.settings) as kv(key, value)
    WHERE tc.tenant_id = current_tenant_id()
),
entity_configs AS (
    SELECT 
        kv.key as config_full_key,
        split_part(kv.key, '.', 1) as module_name,
        split_part(kv.key, '.', 2) as config_key,
        kv.value,
        'entity' as source
    FROM entities e,
         jsonb_each(e.settings) as kv(key, value)
    WHERE e.tenant_id = current_tenant_id()
    AND e.uuid = $1
    AND e.deleted_at IS NULL
),
system_configs AS (
    SELECT 
        cd.module_name || '.' || cd.config_key as config_full_key,
        cd.module_name,
        cd.config_key,
        cd.default_value as value,
        'system' as source
    FROM config_definitions cd
    WHERE ($2::TEXT IS NULL OR $2::TEXT = '' OR cd.module_name = $2)
)
SELECT DISTINCT ON (config_full_key)
    config_full_key,
    module_name,
    config_key,
    value,
    source
FROM (
    SELECT config_full_key, module_name, config_key, value, source, 2 as priority FROM entity_configs
    UNION ALL
    SELECT config_full_key, module_name, config_key, value, source, 1 as priority FROM tenant_configs
    UNION ALL
    SELECT config_full_key, module_name, config_key, value, source, 0 as priority FROM system_configs
) combined
ORDER BY config_full_key, priority DESC
`

type ListTenantEffectiveConfigurationsParams struct {
	EntityID     uuid.UUID `json:"entity_id"`
	ModuleFilter *string   `json:"module_filter"`
}

type ListTenantEffectiveConfigurationsRow struct {
	ConfigFullKey any `json:"config_full_key"`
	ModuleName    string      `json:"module_name"`
	ConfigKey     string      `json:"config_key"`
	Value         any `json:"value"`
	Source        string      `json:"source"`
}

func (q *Queries) ListTenantEffectiveConfigurations(ctx context.Context, arg ListTenantEffectiveConfigurationsParams) ([]*ListTenantEffectiveConfigurationsRow, error) {
	rows, err := q.db.Query(ctx, listTenantEffectiveConfigurations, arg.EntityID, arg.ModuleFilter)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []*ListTenantEffectiveConfigurationsRow{}
	for rows.Next() {
		var i ListTenantEffectiveConfigurationsRow
		if err := rows.Scan(
			&i.ConfigFullKey,
			&i.ModuleName,
			&i.ConfigKey,
			&i.Value,
			&i.Source,
		); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

